\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
COPY (SELECT id,object_id,object_guid,change_id,name,type_name,level,operation_type_id,previous_id,next_id,update_date,start_date,end_date,is_actual,is_active,raw_attributes FROM gar_address_objects ORDER BY object_id,change_id,id) TO :'address_objects_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,change_id,change_id_end,type_id,value,update_date,start_date,end_date,raw_attributes FROM gar_addr_object_params ORDER BY object_id,type_id,change_id,id) TO :'addr_object_params_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,parent_id,child_id,change_id,raw_attributes FROM gar_addr_object_divisions ORDER BY parent_id,child_id,change_id,id) TO :'addr_object_divisions_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,parent_object_id,change_id,region_code,area_code,city_code,place_code,plan_code,street_code,path,update_date,start_date,end_date,is_active,raw_attributes FROM gar_adm_hierarchy ORDER BY object_id,change_id,id) TO :'adm_hierarchy_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,parent_object_id,change_id,region_code,area_code,city_code,place_code,plan_code,street_code,path,update_date,start_date,end_date,is_active,oktmo,raw_attributes FROM gar_mun_hierarchy ORDER BY object_id,change_id,id) TO :'mun_hierarchy_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,object_guid,change_id,house_num,build_num,struc_num,house_type,add_type1,add_num1,add_type2,add_num2,operation_type_id,update_date,start_date,end_date,is_actual,is_active,raw_attributes FROM gar_houses ORDER BY object_id,change_id,id) TO :'houses_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,change_id,change_id_end,type_id,value,update_date,start_date,end_date,raw_attributes FROM gar_house_params ORDER BY object_id,type_id,change_id,id) TO :'house_params_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,object_guid,change_id,number,apart_number,apart_type,operation_type_id,update_date,start_date,end_date,is_actual,is_active,raw_attributes FROM gar_apartments ORDER BY object_id,change_id,id) TO :'apartments_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,change_id,change_id_end,type_id,value,update_date,start_date,end_date,raw_attributes FROM gar_apartment_params ORDER BY object_id,type_id,change_id,id) TO :'apartment_params_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,object_guid,change_id,number,operation_type_id,update_date,start_date,end_date,is_actual,is_active,raw_attributes FROM gar_carplaces ORDER BY object_id,change_id,id) TO :'carplaces_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,change_id,change_id_end,type_id,value,update_date,start_date,end_date,raw_attributes FROM gar_carplace_params ORDER BY object_id,type_id,change_id,id) TO :'carplace_params_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,object_guid,change_id,number,room_type,operation_type_id,update_date,start_date,end_date,is_actual,is_active,raw_attributes FROM gar_rooms ORDER BY object_id,change_id,id) TO :'rooms_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,change_id,change_id_end,type_id,value,update_date,start_date,end_date,raw_attributes FROM gar_room_params ORDER BY object_id,type_id,change_id,id) TO :'room_params_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,object_guid,change_id,number,operation_type_id,update_date,start_date,end_date,is_actual,is_active,raw_attributes FROM gar_steads ORDER BY object_id,change_id,id) TO :'steads_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,object_id,change_id,change_id_end,type_id,value,update_date,start_date,end_date,raw_attributes FROM gar_stead_params ORDER BY object_id,type_id,change_id,id) TO :'stead_params_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT change_id,object_id,address_object_id,operation_type_id,normative_doc_id,change_date,raw_attributes FROM gar_change_history ORDER BY object_id,change_id,address_object_id) TO :'change_history_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT id,name,number,document_date,document_type,document_kind,update_date,organization_name,registration_number,registration_date,acceptance_date,comment,raw_attributes FROM gar_normative_docs ORDER BY id) TO :'normative_docs_file' WITH (FORMAT csv, HEADER true);
COPY (SELECT object_id,object_guid,change_id,level_id,create_date,update_date,is_active,raw_attributes FROM gar_reestr_objects ORDER BY object_id,change_id) TO :'reestr_objects_file' WITH (FORMAT csv, HEADER true);
COMMIT;
